import { Meta, StoryObj } from "@storybook/react";
import { expect, fn, userEvent, within } from "storybook/test";
import { ComponentProps, useState } from "react";
import { CheckboxButtons } from "./checkbox-buttons";
import { buildField } from "@/core/helpers/form-builder";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

type CheckboxButtonsProps = ComponentProps<typeof CheckboxButtons>;

// The selection is controlled by the parent, so the stories keep the comma-separated value in local
// state and forward the callbacks to the args (fn() spies) so they still show up in the Actions panel.
const InteractiveCheckboxButtons = (props: CheckboxButtonsProps) => {
  const [value, setValue] = useState(props.value);
  return (
    <CheckboxButtons
      {...props}
      value={value}
      onChange={(name, newValue) => {
        setValue(newValue);
        props.onChange?.(name, newValue);
      }}
      onOptionClick={(clickedValue) => props.onOptionClick?.(clickedValue)}
    />
  );
};

const options = [
  { value: "one", label: "Alternativ 1" },
  { value: "two", label: "Alternativ 2" },
  { value: "three", label: "Alternativ 3", description: "Beskrivning för tredje alternativet" },
];

const meta = {
  title: "Primitives/Form Fields/Checkbox Buttons",
  component: CheckboxButtons,
  // The global reset removes Storybook's story padding, so a focused toggle button at the edge of
  // the canvas gets its focus ring clipped. Give every story some room in all directions.
  decorators: [
    (Story) => (
      <div style={{ padding: "1rem" }}>
        <Story />
      </div>
    ),
  ],
  parameters: {
    docs: {
      description: {
        component:
          "Group of checkboxes inside a fieldset where the user can select one or more options. The selection " +
          "is controlled by the parent: `value` holds the selected option values as a comma-separated string " +
          '(`"one, two"`) and `onChange` receives the field name and the new string every time a checkbox is ' +
          "toggled; `onOptionClick` receives only the toggled option value. When a `formField` from the form " +
          "builder is given, `name`, `value` and `isDisabled` fall back to the field's `name`, `value` and " +
          "`!isEditable` (`options` is still required; pass `formField.checkBoxOptions`), and " +
          "`formField.isValid === false` sets `data-is-invalid` on the first checkbox, which only changes its " +
          "focus styling. The first checkbox is also the target of `inputRef` and `formField.inputRef`. " +
          "Input ids are built from the option value and index (`one-0`).",
      },
    },
  },
  args: {
    options,
    name: "interests",
    value: "one",
    legend: "Välj ett eller flera alternativ",
    variant: "default",
    isDisabled: false,
    onChange: fn(),
    onOptionClick: fn(),
  },
  argTypes: {
    formField: { table: { disable: true } },
    inputRef: { table: { disable: true } },
    name: { table: { disable: true } },
    onChange: { table: { disable: true } },
    onOptionClick: { table: { disable: true } },
    legendClassName: { table: { disable: true } },
    wrapperClassName: { table: { disable: true } },
    checkboxClassName: { table: { disable: true } },
    descriptionClassName: { table: { disable: true } },
  },
  render: (args) => <InteractiveCheckboxButtons {...args} />,
} satisfies Meta<typeof CheckboxButtons>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {};

const invalidFormField = {
  ...buildField("terms", { validationType: "TERMS_AND_CONDITIONS_CHECKBOX", isRequired: true }),
  isValid: false,
};

// Input ids are built from the option value, so each showcase group gets its own option values to keep
// ids and label targets unique on the page.
const prefixOptions = (prefix: string) => options.map((option) => ({ ...option, value: `${prefix}-${option.value}` }));

export const VariantStates: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="States (variant, isDisabled, value, formField.isValid)" variantType="other">
      <Variant label="variant small">
        <CheckboxButtons {...args} options={prefixOptions("small")} value="small-one" variant="small" />
      </Variant>
      <Variant label="isDisabled">
        <CheckboxButtons {...args} options={prefixOptions("disabled")} value="disabled-one" isDisabled />
      </Variant>
      <Variant label='preselected multiple (value "multi-one, multi-two")'>
        <CheckboxButtons {...args} options={prefixOptions("multi")} value="multi-one, multi-two" legend="Flera valda" />
      </Variant>
      <Variant label="invalid (formField.isValid === false) - only visible as focus styling on the first checkbox">
        <CheckboxButtons
          {...args}
          options={prefixOptions("invalid")}
          value=""
          legend="Godkänn villkoren"
          formField={invalidFormField}
        />
      </Variant>
    </ShowcaseLayout>
  ),
};

const onChangeSpy = fn();
const onOptionClickSpy = fn();

export const TestToggleOptions: Story = {
  args: {
    onChange: onChangeSpy,
    onOptionClick: onOptionClickSpy,
  },
  play: async ({ canvasElement }) => {
    onChangeSpy.mockClear();
    onOptionClickSpy.mockClear();
    const canvas = within(canvasElement);
    const first = canvas.getByRole("checkbox", { name: "Alternativ 1" });
    const second = canvas.getByRole("checkbox", { name: "Alternativ 2" });
    await expect(first).toBeChecked();
    await expect(second).not.toBeChecked();

    await userEvent.click(second);
    await expect(onOptionClickSpy).toHaveBeenCalledWith("two");
    await expect(onChangeSpy).toHaveBeenCalledWith("interests", "one, two");
    await expect(second).toBeChecked();

    await userEvent.click(first);
    await expect(onChangeSpy).toHaveBeenCalledWith("interests", "two");
    await expect(first).not.toBeChecked();
    await expect(second).toBeChecked();
  },
};
